import numpy as np
def read_xyz(fname):
    with open(fname) as f:
        lines=f.read().splitlines()
    n=int(lines[0]); atoms=[]; coords=[]
    for l in lines[2:2+n]:
        p=l.split(); atoms.append(p[0]); coords.append([float(p[1]),float(p[2]),float(p[3])])
    return atoms, np.array(coords)

