import numpy as np
def read_xyz(f):
    l=open(f).read().splitlines(); n=int(l[0]); a=[]; c=[]
    for x in l[2:2+n]:
        p=x.split(); a.append(p[0]); c.append([float(p[1]),float(p[2]),float(p[3])])
    return a,np.array(c)
